135	async function loadServer(job: Job): Promise<Server & { plan: any; gamePlan: any; osTemplate: any; node: any; user: any }> {
136	  const server = await db.server.findUnique({
137	    where: { id: job.serverId! },
138	    // `user` (email) + `node` (publicIp) are needed for the deployment
139	    // confirmation email fired on provision success; the rest is used throughout.
140	    // `gamePlan` — a game order's REAL entitlement (its own ramMB/cpuCores/
141	    // diskGB, the exact numbers advertised and sold), not `plan` (the linked
142	    // basePlan, which only exists because the host only offers 4 discrete VPS
143	    // tiers and a game plan's advertised size gets rounded UP to the nearest
144	    // one that fits — see the long comment where cfg.memory/cores are set).
145	    include: { plan: true, gamePlan: true, osTemplate: true, node: true, user: { select: { id: true, email: true } } },
146	  });
147	  if (!server) throw new Error(`Server ${job.serverId} not found`);
148	  return server as any;
149	}
150	
151	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
152	async function nodeFor(server: any) {
153	  const n =
154	    server.node ??
155	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
156	    (await db.node.findFirst({ where: { enabled: true } }));
157	  if (!n) {
158	    // No Node rows yet — use the env-configured primary via the global client.
159	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
160	  }
161	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
162	}
